-- SEO-Texte für Inhaltsseiten, Produkte und Kollektionen (Auftrag 17.10.2026).
-- Titel ohne " | provibe" (hängt das Layout an), höchstens 60 Zeichen; Beschreibungen höchstens
-- 160 Zeichen. Idempotent: setzt die Werte unabhängig vom bisherigen Stand, Änderungen im
-- Backoffice danach gewinnen (dieses Skript läuft nur einmal als Migration).

update public.page_translations t set seo_title = 'Shop: Eistee mit 15 g Protein, ohne Zucker', seo_description = 'Wildberry, Raspberry Lime und Peach als 9er-Pack, der Mix aus allen drei Sorten, Founder Bundles und Merch. Eistee mit 15 g Protein, ohne Zucker, trinkfertig.' from public.pages p where t.page_id = p.id and t.locale = 'de' and p.handle = 'shop';
update public.page_translations t set seo_title = 'Über uns: Celine und die Idee hinter provibe', seo_description = 'Eine Gründerin, drei Sorten: Wie Celine Grimm aus einer Idee im Studium provibe gemacht hat, den Eistee mit 15 g Protein und ohne Zucker.' from public.pages p where t.page_id = p.id and t.locale = 'de' and p.handle = 'uber-uns';
update public.page_translations t set seo_title = 'Partner: provibe für Gym, Handel und Gastro', seo_description = 'provibe im Sortiment: Eistee mit 15 g Protein für Fitnessstudios, Einzelhandel, Gastronomie und Hotellerie. Direkt beliefert, flexible Mengen, faire Preise.' from public.pages p where t.page_id = p.id and t.locale = 'de' and p.handle = 'partner';
update public.page_translations t set seo_title = 'Kontakt: Schreib dem provibe-Team', seo_description = 'Fragen, Feedback oder eine geschäftliche Anfrage? Schreib uns über das Formular oder an hello@provibe-drinks.de. Wir melden uns innerhalb von 24 Stunden zurück.' from public.pages p where t.page_id = p.id and t.locale = 'de' and p.handle = 'contact';
update public.page_translations t set seo_title = 'Widerrufsformular: Bestellung widerrufen', seo_description = 'Bestellung bei provibe online widerrufen: Formular ausfüllen, abschicken, Bestätigung per E-Mail. Mit Infos zu Frist, Rücksendung und Erstattung.' from public.pages p where t.page_id = p.id and t.locale = 'de' and p.handle = 'widerruf-formular';
update public.page_translations t set seo_title = 'Messe: provibe für Handel und Investoren', seo_description = 'provibe auf Messen und Events: Eistee mit 15 g Protein, ohne Zucker, trinkfertig. Pitch Deck anfragen oder einen Termin mit Gründerin Celine Grimm vereinbaren.' from public.pages p where t.page_id = p.id and t.locale = 'de' and p.handle = 'messe';
update public.product_translations t set seo_title = 'Wildberry Eistee mit 15 g Protein, ohne Zucker', seo_description = 'Beeriger Eistee mit Johannisbeere, Heidelbeere und Erdbeere: 15 g Protein je Dose, ohne Zucker, laktosefrei, 0,33 l. Als 9er-Pack, Pfand extra ausgewiesen.' from public.products p where t.product_id = p.id and t.locale = 'de' and p.handle = 'wildberry';
update public.product_translations t set seo_title = 'Raspberry Lime Eistee mit 15 g Protein, ohne Zucker', seo_description = 'Himbeere trifft spritzige Limette: erfrischender Eistee mit 15 g Protein je Dose, ohne Zucker, laktosefrei, 0,33 l. Als 9er-Pack, Pfand extra ausgewiesen.' from public.products p where t.product_id = p.id and t.locale = 'de' and p.handle = 'raspberry-lime';
update public.product_translations t set seo_title = 'Peach Eistee mit 15 g Protein, ohne Zucker', seo_description = 'Der Klassiker: Pfirsich-Eistee mit feiner Schwarzteenote, 15 g Protein je Dose, ohne Zucker, laktosefrei, 0,33 l. Als 9er-Pack, Pfand extra ausgewiesen.' from public.products p where t.product_id = p.id and t.locale = 'de' and p.handle = 'peach';
update public.product_translations t set seo_title = 'Eistee Mixed: alle drei Sorten mit 15 g Protein', seo_description = 'Alle drei Sorten in einem Paket: 9 Dosen Eistee mit je 15 g Protein, ohne Zucker, laktosefrei, 0,33 l. Wildberry, Raspberry Lime und Peach gemischt.' from public.products p where t.product_id = p.id and t.locale = 'de' and p.handle = 'provibe-eistee-mixed';
update public.product_translations t set seo_title = 'Founder Bundle I: 6 Dosen und Trinkbecher', seo_description = 'Das Starter-Set: je 2 Dosen Wildberry, Raspberry Lime und Peach plus der provibe clear cup. Eistee mit 15 g Protein, ohne Zucker. Limitierte Auflage.' from public.products p where t.product_id = p.id and t.locale = 'de' and p.handle = 'founder-bundle-i';
update public.product_translations t set seo_title = 'Founder Bundle II: 6 Dosen und T-Shirt', seo_description = 'Je 2 Dosen Wildberry, Raspberry Lime und Peach plus das Shirt „Looks like you have great Taste“ im Unisex-Fit. Eistee mit 15 g Protein, ohne Zucker. Limitiert.' from public.products p where t.product_id = p.id and t.locale = 'de' and p.handle = 'founder-bundle-ii';
update public.product_translations t set seo_title = 'Founder Bundle III: Dosen, Becher und Shirt', seo_description = 'Das komplette Set: je 2 Dosen aller drei Sorten, der provibe clear cup und das Shirt „Looks like you have great Taste“. Eistee mit 15 g Protein, ohne Zucker.' from public.products p where t.product_id = p.id and t.locale = 'de' and p.handle = 'founder-bundle-iii-1';
update public.product_translations t set seo_title = 'provibe clear cup: Trinkbecher mit Strohhalm', seo_description = 'Der provibe Trinkbecher aus klarem Kunststoff mit Deckel und Strohhalm. Für Eistee auf Eis, unterwegs oder im Büro. Einzeln oder im Founder Bundle.' from public.products p where t.product_id = p.id and t.locale = 'de' and p.handle = 'provibe-clear-cup';
update public.product_translations t set seo_title = 'provibe shirt: „Looks like you have great Taste“', seo_description = 'Das provibe T-Shirt in Unisex-Passform, Größen S bis L: kleines Logo vorn, „Looks like you have great Taste“ auf dem Rücken. Einzeln oder im Founder Bundle.' from public.products p where t.product_id = p.id and t.locale = 'de' and p.handle = 'provibe-shirt';
update public.collection_translations t set seo_title = 'Alle Produkte: Eistee, Bundles und Merch', seo_description = 'Das ganze Sortiment: Eistee mit 15 g Protein in drei Sorten, der Mix, limitierte Founder Bundles, Trinkbecher und Shirt. Ohne Zucker, trinkfertig, 0,33 l.' from public.collections c where t.collection_id = c.id and t.locale = 'de' and c.handle = 'all';
update public.collection_translations t set seo_title = 'Produkte: Sorten, Mix und Founder Bundles', seo_description = 'Wildberry, Raspberry Lime und Peach, der Mix aus allen dreien und die Founder Bundles. Eistee mit 15 g Protein, ohne Zucker, laktosefrei, 0,33 l je Dose.' from public.collections c where t.collection_id = c.id and t.locale = 'de' and c.handle = 'alle-produkte';
update public.collection_translations t set seo_title = 'Eistee mit 15 g Protein: alle Sorten', seo_description = 'Wildberry, Raspberry Lime, Peach und der Mix: Eistee mit 15 g Protein je Dose, ohne Zucker, laktosefrei, trinkfertig. Als 9er-Pack, Pfand extra ausgewiesen.' from public.collections c where t.collection_id = c.id and t.locale = 'de' and c.handle = 'eistee';
update public.collection_translations t set seo_title = 'Founder Bundles: limitierte Sets mit allen Sorten', seo_description = 'Drei limitierte Sets: je 2 Dosen Wildberry, Raspberry Lime und Peach, wahlweise mit Trinkbecher, Shirt oder beidem. Eistee mit 15 g Protein, ohne Zucker.' from public.collections c where t.collection_id = c.id and t.locale = 'de' and c.handle = 'aktion';
